CREATE OR REPLACE VIEW public.iscrizioni_pubbliche WITH (security_barrier = true) AS SELECT i.id, i.evento_id, i.atleta_id, i.stato, coalesce(i.snapshot_nome,a.nome) AS nome, coalesce(i.snapshot_cognome,a.cognome) AS cognome, coalesce(i.snapshot_team,a.nome_societa) AS nome_societa, coalesce(i.snapshot_peso_kg,a.peso_kg) AS peso_kg, coalesce(i.categoria_peso,i.snapshot_categoria) AS categoria, coalesce(i.disciplina,a.disciplina) AS disciplina, i.created_at FROM public.iscrizioni i JOIN public.atleti a ON a.id=i.atleta_id;